    "5981": "Cerrar",
    "6227": "Los archivos deben ser analizados por IA para poder ser clasificados, si hay demasiados el proceso puede llevar bastante tiempo. El modo de funcionamiento determina si los resultados del análisis se almacenan en caché en el servidor.",
    "6229": "Descargar directorios, recursos de red, libros electrónicos, cómics, música y otros archivos públicos.",
    "6230": "Tus resultados de análisis solo se guardan localmente, no se almacenan en caché en el servidor, protegiendo así la soberanía de tus datos. Sin embargo, no podrás beneficiarte del efecto de aceleración que proporciona la caché del servidor.",
