    "7647": "Error en la actualización de la base de datos",
    "7648": "Reanudar",
    "7649": "Salir de la aplicación",
    "7650": "Se detectó una versión anterior de la base de datos (1.x.x).\\n\\nLa versión 2.0 de esta aplicación ya no admite la actualización de la base de datos directamente desde la versión anterior. \\n\\nRealice una de las siguientes operaciones:\\n1. Primero instale y ejecute la versión 1.3.2 para completar la actualización de transición y luego instale la versión 2.0. \\n2. Elimine manualmente el archivo de base de datos antiguo (firefly-ai-folder.db) y reinicie la aplicación para crear una nueva arquitectura 2.2. \\n\\nLa aplicación se cerrará ahora.",
