    "9771": "Otra solución externa para ejecutar localmente servicios de modelos grandes, es entre un 20% y un 40% más lenta que el motor de IA integrado de Firefly, pero tiene buena compatibilidad de hardware y se recomienda su instalación.",
    "9772": "La plataforma de experiencia de modelo proporcionada por NVIDIA alberga una variedad de modelos grandes convencionales y actualmente ofrece pruebas gratuitas.",
