    "9784": "SentirTiempo",
    "9785": "La nueva interfaz diaria de modelo grande de SenseTime se encuentra actualmente en el período beta público y proporciona una cuota de llamadas gratuitas.",
    "9787": "El modelo liviano de alto rendimiento de SenseTime",
    "9789": "El modelo de razonamiento extremadamente rápido de SenseTime",
    "9792": "Modelo de inferencia rápida de DeepSeek alojado en SenseTime",
    "9794": "Regístrese y obtenga una prueba de $10, no se requiere tarjeta de crédito. El crédito es válido dentro de 3 meses. Incluye los modelos Jamba Large y Jamba Mini.",
    "9795": "Israel",
    "9800": "Alibaba Cloud Bailian (versión internacional)",
    "9801": "Después del registro, cada modelo de Tongyi Qianwen recibirá 1 millón de tokens gratis, válidos por 90 días (área internacional/Singapur). No se requiere tarjeta de crédito.",
    "9803": "Clave API de \"prueba\" gratuita, no se requiere tarjeta de crédito. 1000 llamadas API por mes. Sólo para uso no comercial.",
    "9804": "Canadá",
    "9816": "Plan \"Experimental\" gratuito, no se requiere tarjeta de crédito. Aproximadamente mil millones de tokens por mes. Se pueden utilizar palabras clave para mejorar el modelo.",
    "9825": "AI Zhipu",
    "9826": "Ofrece modelos gratuitos para siempre, no se requiere tarjeta de crédito.",
    "9829": "Gratis, no se requiere tarjeta de crédito. Razonamiento extremadamente rápido (alrededor de 2600 token/s). Límite diario de 1 millón de Tokens. Límite de contexto de 8K de archivos gratuitos. Está previsto que llama3.1-8b quede obsoleto el 27 de mayo de 2026.",
    "9835": "10.000 Neuronas gratis cada día. La versión gratuita ofrece más de 50 modelos.",
    "9841": "Créditos de creación de prototipos gratuitos para todos los usuarios de GitHub. Contiene más de 45 modelos. Hay un límite para una sola solicitud (8K de entrada/4K de salida).",
    "9846": "Gratis, no se requiere tarjeta de crédito. Inferencia de LPU extremadamente rápida.",
    "9851": "Proporcione a los usuarios gratuitos una cuota mensual de servicio de inferencia de 100.000 veces. Rutas a proveedores como Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra y más. Soporta miles de modelos.",
    "9855": "Modelo gratuito, no se requiere tarjeta de crédito. `kilo-auto/free` enruta automáticamente a minimax/minimax-m2.5:free (80%) y stepfun/step-3.5-flash:free (20%).",
    "9857": "Puerta de enlace API perfecta. No es necesario registrarse para el acceso básico. Soporta más de 30 modelos. Cumple con el RGPD.",
    "9858": "Reino Unido",
    "9862": "ModeloScope",
    "9863": "Proporciona servicios de inferencia API gratuitos a usuarios registrados. Debe vincular su cuenta de Alibaba Cloud y completar la autenticación de nombre real.",
    "9868": "Regístrese y obtenga $1 en crédito gratis, no se requiere tarjeta de crédito. Más de 60 modelos de código abierto están disponibles a través de una API compatible con OpenAI. Con sede en la UE.",
    "9869": "Países Bajos",
    "9872": "Regístrese y obtenga $5 en crédito gratis, no se requiere tarjeta de crédito. Proveedor soberano de la UE con centro de datos ubicado en Noruega. Sin límites de tarifas, sin arranques en frío.",
    "9874": "Gratis con límites de uso cualitativos. Ofrece más de 400 modelos de la biblioteca de Ollama. No es compatible con OpenAI SDK, utilice [Ollama API](https://docs.ollama.com/cloud).",
    "9877": "Terminal de IA de OVHcloud",
    "9878": "Perfil anónimo gratuito (sin clave API, no se requiere registro): límite de 2 RPM por modelo por IP. Alojamiento de más de 40 modelos de peso de código abierto en la UE. Compatible con el SDK de OpenAI.",
    "9882": "Cuota de token diaria gratuita, no se requiere tarjeta de crédito. Diseñado para juegos de rol y creación de historias.",
    "9885": "El número de solicitudes por minuto está limitado a 20. Si la solicitud es demasiado rápida en un corto período de tiempo, se activará el límite de frecuencia (debe esperar 1 minuto y volver a intentarlo).",
    "9886": "Singapur",
    "9889": "El modelo rápido y eficiente de Sapiens AI respalda la comprensión de imágenes.",
