    "20672": "Límite de cantidad para el reconocimiento OCR de documentos (número de imágenes incrustadas en documentos de Office / número de páginas en documentos PDF)",
    "20673": "Deshabilitado (0)",
    "20674": "ítems/página",
    "20675": "Precisión del reconocimiento OCR",
    "20676": "Seleccione el nivel de precisión para el reconocimiento de texto mediante OCR. El OCR ultrarrápido es adecuado para la mayoría de los escenarios; el OCR de alta precisión reconoce con mayor exactitud, pero requiere un poco más de tiempo.",
    "20677": "OCR ultrarrápido",
    "20678": "Se completa en 1~2 segundos por imagen, adecuado para la mayoría de los escenarios",
    "20679": "OCR de alta precisión",
    "20680": "Se completa en 2~4 segundos por imagen, mejora la precisión de reconocimiento",
    "20681": "Reutiliza los datos al reanar",
    "20682": "Si el archivo se ha actualizado, desactive esta opción; de lo contrario, si la información básica del archivo ya existe, omita la obtención de dicha información. La información básica incluye: tipo de archivo, miniatura, metadatos, contenido del archivo",
    "20683": "Acelera el análisis y no volverá a obtener la información de la fase de análisis estándar",
    "20684": "Ejemplo: Característica de una colección de archivos como unidad global: conjuntos de archivos con sufijo numérico en el nombre del archivo, por ejemplo: 1.txt, 2.txt, 3.txt",
    "20686": "Identifique unidades completas como archivos en serie, álbumes de pistas, directorios de proyectos, etc., y admita indicadores personalizados para la identificación de unidades",
    "20687": "Activar identificación de unidades mínimas",
    "20688": "Las siguientes categorías se identifican de forma obligatoria y no es necesario activarlas: directorios del sistema, directorios de instalación de software, proyectos de ingeniería, paquetes de juegos, conjuntos de datos/modelos de IA, caché y LFS, entornos virtuales",
    "20689": "Una vez activado, los directorios identificados como unidades mínimas omitirán el análisis individual de cada archivo",
    "20690": "Archivos en serie: documentos o imágenes numerados consecutivamente (p. ej., 01.jpg, 02.jpg, 03.jpg)",
    "20691": "Álbum de audio: conjunto de archivos de pistas de un mismo álbum (como .flac, .mp3)",
    "20692": "Proyecto de diseño: proyecto de diseño que incluye archivos de proyecto y directorios de recursos (como .prproj, .aep, .blend)",
    "20693": "Sugerencia: al desactivarlo, todos los archivos se analizarán de forma independiente; aplicable a escenarios que requieran generar descripciones y etiquetas para cada archivo de forma individual",
    "20694": "Palabras clave de identificación de la unidad mínima",
    "20695": "Debe activarse el interruptor superior para que surta efecto",
    "20696": "Define qué tipo de conjunto de archivos debe considerarse una unidad global para ajustar el criterio de identificación del modelo",
    "20698": "El interruptor de arriba no está activado; la sugerencia no es efectiva por ahora.",
    "20699": "El directorio identificado como unidad mínima se tratará en su totalidad como un archivo, para evitar generar demasiados resultados de análisis fragmentados.",
    "20701": "Se requiere la instalación de la dependencia externa ffprobe",
