    "20716": "Admite la selección múltiple por lotes para agregar nuevas etiquetas y eliminarlas en masa en las etiquetas de los archivos objetivo, completando el perfil semántico de los archivos.",
    "20717": "Verificación de duplicados segura",
    "20718": "Analiza de forma inteligente con FireFly Omni y limpia de manera segura los archivos redundantes o duplicados; todas las eliminaciones se trasladan al papelera del sistema.",
