    "21835": "Agrupación jerárquica nativa no supervisada en el lado del dispositivo, salida de gráficos instantáneos a nivel de milisegundos y soporte para guía de palabras en lenguaje natural y ajuste fino en línea.",
    "21837": "Se planifican en profundidad de un extremo a otro tres conjuntos de soluciones finales completas de árbol de directorios jerárquicos a partir del modelo grande, que se pueden comparar y seleccionar directamente sin pasos tediosos.",
