    "21840": "La desfragmentación incremental se utiliza para agregar nuevos archivos a directorios virtuales existentes. Su espacio de trabajo actual no ha guardado ningún directorio virtual. Seleccione el modo de organización apropiado desde arriba para completar y guardar los directorios virtuales.",
