    "22246": "Formato de imagen no admitido",
    "22247": "Encontré una herramienta de inteligencia artificial gratuita de código abierto súper fácil de usar, \"Firefly AI Folder\", que puede ordenar el escritorio desordenado, el directorio de descargas, etc. con un solo clic, buscar contenido de imágenes, texto, audio y video en lenguaje natural en segundos, y el video se puede incluso ubicar en un intervalo de tiempo específico, ¡y la IA categoriza/cambia nombres/etiquetas/describe/miniaturas/archivos/limpia automáticamente! Utilice capacidades de IA locales para garantizar la privacidad. No se requiere tarjeta gráfica. Las computadoras portátiles delgadas y livianas con poca memoria pueden ejecutar IA con alta calidad. La innovadora tecnología de organización de directorios virtuales garantiza la seguridad de los archivos. ¡Ven y pruébalo!",
    "22248": "No se pueden determinar los archivos que se van a ordenar. Seleccione nuevamente e inténtelo nuevamente.",
