    "22258": "Actualmente en modo de clasificación completo ({count} elementos en total, superando los {limit} elementos recomendados para un solo lote). Un único cálculo a gran escala aumentará significativamente el consumo de tiempo y memoria de la IA:",
    "22259": "Un único cálculo a escala extremadamente grande aumentará significativamente el uso de la memoria y el tiempo de respuesta de la IA (complejidad O(N²)), y la granularidad de la agrupación de directorios puede volverse más amplia.",
