    "22316": "Tales como: clasificación por año y financiación, archivo de documentos del proyecto...",
    "22320": "Ejemplos: agregar más puntos a historias de comedia; reducir el peso de los indicadores técnicos; La descripción de contenido multimodal se centra en las relaciones de los personajes, traducida como {activeLanguage}",
    "22321": "Ejemplo: los nombres de archivos inteligentes deben traducirse al {activeLanguage}. Se puede generar un máximo de 20 etiquetas y cada etiqueta no debe exceder las 2 palabras. Se debe extraer al menos una etiqueta del nombre del archivo, y las demás deben extraerse de este conjunto: [Felicidad, Dolor, Resentimiento,...]",
    "22334": "[Reconstrucción del motor de IA] El motor de IA básico integrado está listo para usar desde el primer momento, con un motor de IA avanzado Firecore/nube opcional para mejorar el análisis bajo demanda.",
    "22335": "[Compatible con computadoras de baja configuración] Reconstruya la arquitectura de IA de alta velocidad basada en la inferencia de la CPU, funcionando sin problemas en dispositivos con poca memoria sin tarjetas gráficas independientes",
    "22336": "[Motor de IA Firecore independiente] Se puede ejecutar independientemente del programa principal para proporcionar capacidades de IA a aplicaciones de terceros",
    "22337": "[Búsqueda semántica multimedia] Las imágenes, audios y videos admiten la recuperación del lenguaje natural y la búsqueda de contenido por semántica, imágenes y voces.",
    "22338": "[ASR de voz a texto] Transcribe rápidamente conversaciones de audio y video a texto para recuperarlas y archivarlas fácilmente",
    "22339": "[Síntesis de voz TTS] Texto a voz, más de 50 sonidos integrados, admite clonación de sonido de 3 segundos y lee novelas documentales en voz alta",
    "22340": "[Actualización de etiquetas de archivos] Enriquezca los tipos de etiquetas de hechos, las etiquetas son más precisas e interpretables y el árbol de etiquetas admite 10 niveles de expansión",
    "22341": "[Optimización del material del creador] Para diseñadores y medios propios, optimización especial de la clasificación de materiales de audio, vídeo e imágenes.",
    "22342": "[Detección mejorada de contenido confidencial] Identifique segmentariamente contenido pornográfico, violento, terrorista, político, abusivo, sangriento y otros contenidos ilegales y sus subcategorías",
    "22343": "[Cinco modos principales de clasificación por lotes] Plano de identidad / agrupación inteligente / directorio externo generado por IA / árbol de directorios de derivación de archivos / árbol de directorios personalizado, procesando miles de archivos en segundos",
    "22344": "[Plan de identidad (recomendado)] Seleccione roles de la industria, optimización de cuatro etapas y clasifique todos los archivos en milisegundos en el lado del cliente",
    "22345": "[Clúster inteligente] Clúster no supervisado de HAC final, genera árboles de directorios en milisegundos, clasifica todos los archivos en segundos y admite ajustes en tiempo real",
    "22346": "[Directorio externo generado por IA] Copie las palabras clave a Doubao, Kimi, ChatGPT con un solo clic y obtenga una vista previa y organice los resultados en tiempo real",
    "22347": "[Derivar árboles de directorios a partir de archivos] El motor de IA avanzado genera 3 conjuntos de candidatos de directorio a la vez y se selecciona la clasificación automática",
    "22348": "[Árbol de directorios personalizado] Pegue el directorio Markdown, obtenga una vista previa de dos columnas en tiempo real y cree reglas de organización exclusivas",
    "22349": "[Optimización de la interfaz de usuario en profundidad] Reconstruya la estructura de la página de configuración, agregue una nueva guía y entrada de ayuda y haga que la operación sea más intuitiva.",
    "22350": "Se produce una excepción en la interfaz.",
    "22351": "El proceso de representación de la interfaz finalizó y la aplicación no pudo reanudarse automáticamente. Reinicie la aplicación e inténtelo de nuevo.",
