    "23147": "[Análisis mejorado] + Análisis completo de IA, que incluye puntajes de calidad e imágenes detalladas, descripciones de contenido de audio y más etiquetas",
    "23151": "Modo de análisis y recuperación de pantalla de vídeo.",
    "23152": "Determina la velocidad de análisis cuando el archivo se importa y clasifica por primera vez, y si la escena específica que \"pasa rápidamente\" en el medio del video se puede buscar con precisión en la barra de búsqueda. La respuesta de búsqueda es siempre instantánea en milisegundos.",
    "23153": "Personalizado",
    "23154": "Cobertura de análisis de profundidad de pantalla",
    "23155": "Vídeo corto de apoyo sanitario completo (primeros 5 minutos)",
    "23156": "La versión gratuita disfruta de alta definición y la capacidad de evitar fugas y detección completa del estado. A los vídeos largos de más de 5 minutos se les da prioridad para cubrir la parte frontal, y la actualización a Pro desbloquea un análisis en profundidad de toda la película.",
    "23157": "Archivado extremadamente rápido",
    "23158": "Análisis 3~5 segundos/película",
    "23159": "Solo se extraen nombres de archivos inteligentes y etiquetas de clasificación, y solo se capturan 8 imágenes congeladas, lo que no consume potencia informática.",
