    "23177": "Abierto",
    "23178": "(Se recomiendan entre 40 y 60 fotografías para uso diario, y se pueden ajustar a 120 y 240 fotografías para una búsqueda detallada de materiales)",
    "23179": "Cuántos fotogramas clave se pueden extraer de un solo vídeo y enviarlos a la IA para su comprensión. Cuantas más capturas de pantalla capture, es menos probable que se pierda tomas detalladas en videos largos, pero el tiempo que lleva ordenarlas y analizarlas por primera vez aumentará en consecuencia.",
    "23180": "El cambio de lentes captura la agudeza",
    "23181": "Sensible (recomendado)",
    "23182": "Extremadamente alto (anti-deglución)",
    "23183": "Capture solo las escenas principales de toda la película.",
    "23184": "Pantalla de representante de selección de segmento estándar",
    "23185": "Primer plano del coche deportivo transitorio rescatado en 1,6 segundos",
    "23186": "Precisión de reconocimiento de pantalla",
    "23187": "La velocidad de clasificación y análisis se duplica, lo que es adecuado para clasificación por lotes y cuadernos delgados y livianos.",
    "23188": "El cuerpo principal y los pequeños detalles se pueden reconocer con mayor precisión. Se recomienda encender la tarjeta gráfica independiente.",
    "23189": "Límite superior de reconocimiento de línea de audio y vídeo",
    "23190": "Extraiga solo los primeros N segundos de líneas de pista de audio desde el comienzo del video (no afecta el audio puro). Cuanto más tiempo se reconozcan las etiquetas de línea, más completas serán y el análisis llevará un poco más de tiempo.",
    "23191": "Se estima que la primera vez que se clasifica un solo vídeo lleva mucho tiempo",
    "23192": "Medido según análisis de vídeo cada 5 minutos.",
    "23193": "El consumo de tiempo sólo se produce una vez durante la primera clasificación; la búsqueda es instantánea en milisegundos.",
    "23194": "Aproximadamente {min} minutos",
    "23195": "Extremadamente rápido (aproximadamente {speed}x procesamiento en tiempo real)",
    "23196": "Moderadamente equilibrado (aproximadamente {speed}x procesamiento en tiempo real)",
    "23197": "Profundamente refinado (aproximadamente {speed}x procesamiento en tiempo real)",
    "23198": "Comprensión de la IA en pantalla",
    "23199": "Reconocimiento de voz de línea",
    "23200": "Desembalaje e indexación básicos",
    "23201": "Línea en tiempo real",
    "23202": "Reconocimiento de linea",
    "23203": "Pista de audio",
    "23204": "Gastos generales básicos",
    "23205": "Respuesta instantánea de milisegundos al buscar",
    "23206": "En esta configuración, en una computadora sin una tarjeta gráfica independiente, la clasificación será más lenta que el video en sí, por lo que es adecuado para ordenar lentamente en segundo plano; cuando está equipado con una tarjeta gráfica independiente, la suavidad se puede acelerar varias veces.",
    "23207": "La versión gratuita analiza los primeros 5 minutos de cada vídeo.",
    "23208": "Actualizar a la membresía Pro puede desbloquear el análisis completo de todo el video, admitiendo un solo video de más de 2 horas.",
    "23209": "Actualiza a Pro ahora",
    "23210": "En el modo de motor clásico liviano, use lenguaje natural para describir la imagen (como \"auto deportivo rojo\", \"sofá a la izquierda\") para la recuperación de imágenes entre modos. Apague los dispositivos de gama baja para ahorrar memoria.",
    "23211": "Cuando está activado, las descripciones de imágenes en lenguaje natural se pueden utilizar para recuperar imágenes directamente. Nota: Este canal solo recupera imágenes puras y no afecta documentos, líneas de audio y video ni fragmentos de video.",
    "23212": "Estado y mantenimiento del índice semántico.",
    "23213": "Al cambiar el engranaje del motor de IA, cambiar la dimensión del vector MRL o encontrar una recuperación de vectores inexacta, puede activar manualmente una reconstrucción completa del índice de la base de datos.",
    "23217": "Se han restaurado los parámetros recomendados para la extracción del contenido del archivo de la escena actual.",
    "23218": "Escenario válido para el directorio de trabajo actual: {intent}. Controle la extracción de texto, el reconocimiento OCR y la generación de portadas de Office.",
    "23219": "Extracción de contenido de documentos y textos.",
    "23220": "El límite superior del tamaño de extracción de texto (incluido OCR)",
    "23221": "El tamaño máximo de extracción de un único indicador de texto (texto/documento/OCR/HTML). El contenido demasiado largo se truncará automáticamente para evitar ocupar demasiado espacio de almacenamiento.",
    "23222": "Número de página de extracción de texto del documento PDF",
    "23223": "Controla las primeras páginas de los documentos PDF que se extraerán para la indexación de texto y vectores.",
    "23224": "Todas las copias no están limitadas.",
    "23225": "Página",
    "23226": "Activar la captura de pantalla de la portada del documento de Office",
    "23227": "Admite la exportación de la página de inicio de documentos de Office como miniaturas de portada, pero aumentará el tiempo necesario para el análisis de Office y el PDF no se verá afectado. Requiere la instalación de LibreOffice.",
    "23228": "Habilitar: llame a LibreOffice para cambiar la página de inicio a una portada en miniatura",
    "23229": "Desactivado: omitir la extracción de la imagen de portada de Office",
    "23230": "Entorno dependiente: LibreOffice",
    "23231": "Admite conversión de página completa y extracción de imágenes de portada de archivos de Office",
    "23232": "Sin embargo, aumentará el tiempo necesario para la extracción del contenido y el PDF no se verá afectado.",
    "23233": "Reconocimiento y procesamiento de texto OCR",
    "23234": "Habilitar el reconocimiento inteligente de OCR de imágenes",
    "23235": "Percepción inteligente a nivel de milisegundos de si hay texto en la imagen y reconocimiento OCR si lo hay.",
    "23236": "Identifique y extraiga automáticamente contenido de texto en imágenes, admitiendo búsqueda de texto completo y etiquetas visuales",
    "23237": "Número máximo de reconocimientos OCR en documentos",
    "23238": "La cantidad de imágenes incrustadas en documentos de Office/el límite superior de la cantidad de páginas reconocidas en archivos PDF escaneados. 0 significa omitir el OCR del documento.",
    "23239": "Nivel de precisión del reconocimiento OCR",
    "23240": "Seleccione el nivel de precisión del reconocimiento de texto OCR. El OCR extremadamente rápido es adecuado para la mayoría de escenarios; El reconocimiento OCR de alta precisión es más preciso pero lleva un poco más de tiempo.",
    "23241": "OCR extremadamente rápido (pequeño)",
    "23242": "Se puede completar una sola imagen en 1 a 2 segundos, con un rendimiento excelente y adecuado para la mayoría de las imágenes diarias.",
    "23243": "OCR de alta precisión (pequeño)",
    "23244": "Se puede completar una sola imagen en 2 a 4 segundos, lo que mejora la tasa de reconocimiento de escritura a mano compleja e imágenes de bajo contraste.",
    "23245": "Si el archivo se ha actualizado, desactive esta opción; de lo contrario, la información básica existente (tipo de archivo, miniatura, metadatos, texto) se reutilizará directamente para acelerar el análisis.",
    "23246": "El análisis se acelera enormemente, saltándose la etapa básica de extracción de información objetiva existente.",
    "23247": "Ingrese una extensión legal, como .cr3 o docx.",
