    "23298": "Inclusión estimada: {inPct}%",
    "23299": "Exclusiones esperadas: {outPct}%",
    "23301": "Se han establecido {count} extensiones de destino. Solo los archivos que coincidan con estas extensiones pueden ingresar a la cola de análisis de IA después de guardarlos.",
    "23303": "Agregar exclusiones",
    "23304": "Agregar reglas de exclusión de directorio",
    "23305": "Tipo de coincidencia",
    "23306": "Valor de coincidencia",
    "23307": "Ingrese un nombre o patrón para excluir",
    "23308": "Observaciones (opcional)",
    "23309": "Por ejemplo: directorio de salida de compilación temporal local",
    "23310": "Guardar regla de exclusión",
    "23311": "Actualmente no existen reglas de exclusión exclusivas para el directorio de trabajo actual y solo cumplen con la línea base global del sistema a continuación.",
    "23312": "Si hay compilaciones temporales dedicadas, cachés o carpetas privadas en este directorio que no requieren análisis, puede hacer clic en \"Agregar exclusiones\" arriba.",
    "23313": "Eliminar esta regla",
    "23315": "Ir a la gestión de configuración del sistema",
    "23316": "Las siguientes reglas pertenecen a la línea de seguridad de todo el sistema (como .git, node_modules, .VirtualDirectory, etc.). El directorio actual lo hereda y protege automáticamente, y las reglas del directorio no pueden sobrescribir ni cancelar las reglas del sistema.",
    "23317": "El entorno actual no puede abrir directamente el directorio local",
    "23318": "No se pudo abrir el directorio",
    "23319": "Se ha activado la supervisión automática: los nuevos cambios de archivos se agregarán automáticamente a la cola de análisis de IA",
    "23320": "Se ha pausado la supervisión automática: los cambios de archivos externos ya no se rastrearán automáticamente",
    "23321": "No se pudo actualizar el estado de escucha del directorio",
    "23322": "No hay archivos nuevos o modificados en el directorio actual",
    "23323": "La interfaz de escaneo no está disponible",
    "23324": "Error al volver a escanear el directorio",
    "23325": "No se encontraron carpetas vacías, ¡la estructura del directorio es muy ordenada!",
    "23326": "Error al escanear la carpeta vacía",
    "23327": "Los datos del análisis del espacio de trabajo se han restablecido de forma segura y los archivos compartidos por otros directorios se han conservado completamente de acuerdo con la ley.",
    "23328": "Restablecer interfaz no detectada",
    "23329": "Restablecer excepción del espacio de trabajo",
    "23330": "El directorio de trabajo '{name}' ha sido eliminado de la aplicación.",
    "23331": "No se pudo eliminar el directorio de trabajo",
    "23332": "Eliminar excepción del directorio de trabajo",
    "23333": "El flujo de trabajo se ha desvinculado y la instantánea actual de la lista blanca se ha conservado de forma segura.",
    "23334": "No se pudo desvincular el flujo de trabajo",
    "23335": "Excepción de flujo de trabajo no vinculante",
    "23336": "La lista blanca se borró y volvió al modo de admisión completa estándar.",
    "23337": "No se pudo borrar la lista vacía",
    "23338": "Borrar excepción de lista vacía",
    "23339": "Mantenimiento y gestión de directorios.",
    "23340": "Supervise los cambios de archivos, realice un análisis completo, limpie carpetas vacías o restablezca los datos del análisis de IA del directorio actual.",
    "23341": "Para configurar",
    "23342": "Ver esta carpeta en el explorador del sistema operativo",
    "23343": "Abrir carpeta",
    "23344": "Intención de escena:",
    "23345": "Flujo de trabajo vinculante:",
    "23346": "Sin consolidar (modo estándar)",
    "23347": "Tiempo agregado:",
    "23348": "Supervisar automáticamente los cambios de archivos (Auto Watch)",
    "23349": "Monitoreo en tiempo real",
    "23350": "Detecta archivos nuevos, modificados y eliminados en el directorio actual en tiempo real. Después de abrirlos, los archivos nuevos se sincronizarán automáticamente y se agregarán a la cola de análisis inteligente de IA.",
    "23351": "Reescaneo y detección de cambios",
    "23352": "Realice una comparación completa de los archivos del disco físico para verificar si hay archivos nuevos o cambios agregados sin conexión y, opcionalmente, envíelos a la cola de análisis.",
    "23353": "Volver a escanear",
    "23354": "Escanear y limpiar carpetas vacías",
    "23355": "Escanee recursivamente el directorio actual en busca de carpetas vacías que queden después de ordenar o eliminar. Admite la visualización de detalles y la limpieza por lotes con un solo clic.",
    "23357": "Vuelva a ejecutar el asistente de configuración de escenarios",
    "23358": "Reinicie el Asistente minimalista y el sistema detectará nuevamente el contenido del directorio y proporcionará recomendaciones predeterminadas de \"Organización rápida/Galería creativa/Materiales de video/Desorden del escritorio\".",
    "23359": "Ejecutar asistente",
    "23360": "Enlace de flujo de trabajo y protección de instantáneas de lista blanca",
    "23361": "Atado: {name}",
    "23362": "Sin consolidar (modo genérico)",
    "23366": "Desvincular flujo de trabajo",
    "23368": "Ir al flujo de trabajo vinculante",
    "23369": "Instantánea de la extensión vigente:",
    "23370": "Restablecer de forma segura los datos de análisis del catálogo",
    "23371": "Borre las etiquetas AI, el caché del guión gráfico y el índice de texto de todos los archivos en el directorio actual. Protegidos por el mecanismo de protección huérfana entre espacios de trabajo, los archivos compartidos nunca se dañarán accidentalmente.",
    "23372": "Restablecer datos...",
    "23373": "Eliminar el directorio de trabajo de la aplicación.",
    "23374": "Desvincule este directorio dentro de la aplicación y borre sus registros de índice. Esta operación no afecta ni elimina en absoluto los archivos reales del disco físico.",
    "23375": "Quitar directorio...",
    "23376": "¿Confirmar el reinicio seguro '{name}'?",
    "23377": "Esta operación borrará los resultados del análisis de IA y el caché del guión gráfico de todos los archivos en el directorio actual, pero no eliminará los archivos reales en el disco físico.",
    "23378": "Protegido por el mecanismo de protección huérfana: los archivos compartidos a los que hacen referencia otros espacios de trabajo están protegidos automáticamente por retención inmune.",
    "23379": "Confirmar reinicio seguro",
    "23380": "¿Está seguro de que desea eliminar el directorio de trabajo \"{name}\"?",
    "23381": "¿Está seguro de que desea eliminar este directorio de trabajo de la aplicación? Se limpiarán los datos de análisis e indexación de archivos relevantes.",
    "23382": "Seguro y protegido: los archivos y carpetas del disco físico están 100% intactos.",
    "23383": "Confirmar eliminación",
    "23384": "¿Está seguro de desvincular el flujo de trabajo?",
    "23385": "Después de desvincular el flujo de trabajo, el directorio cambiará al modo de administración general y ya no se regirá por reglas de flujo de trabajo específicas.",
