    "28428": "Permisos mínimos e instrucciones de seguridad para interfaces locales.",
    "28429": "La interfaz abierta local es solo para que los agentes locales autorizados consulten metadatos de análisis de archivos y envíen borradores de edición multidimensional. No tiene autoridad para reescribir o eliminar archivos físicos directamente. Todos los planes de organización impulsados ​​por agentes externos se envían como borradores y usted debe confirmarlos explícitamente en el escritorio antes de que puedan implementarse.",
    "28430": "La palabra de indicación de unidad mínima personalizada depende de la capacidad de comprensión del modelo de lenguaje del motor generativo y actualmente no está habilitada.",
    "28431": "Motor de búsqueda",
    "28432": "Elija diferentes modos según sus necesidades. El análisis exhaustivo es el que lleva más tiempo pero tiene la mayor precisión; El análisis estándar es el más rápido. El análisis mejorado y el análisis integral requieren que el motor generativo esté encendido.",
