    "28534": "Reglas globales de exclusión de archivos",
    "28535": "Configure los archivos que no se muestran en el directorio real para que no entren en el análisis de IA para mejorar la eficiencia del análisis y admitir la verificación y limpieza de duplicaciones por lotes para proteger estos archivos excluidos.",
    "28536": "El cerebro de búsqueda central de todo el software (elija uno de dos). Cambiar el motor restablecerá automáticamente el índice de búsqueda de todos los archivos.",
    "28537": "Comprenda el contenido hablado en audio y video y conviértalo en subtítulos de texto. Puede buscar archivos directamente mediante diálogo.",
    "28538": "Lea el documento con una agradable voz de persona real y admita la lectura sin conexión y la escucha de libros y materiales con auriculares.",
    "28539": "Identifique y marque automáticamente fotografías privadas y contenido confidencial para evitar situaciones embarazosas al transmitir o ver en público.",
    "28540": "Puede ver el contenido de archivos especiales, como archivos comprimidos, sin descomprimirlos, y buscar directamente información interna.",
    "28541": "Widgets de extensión inteligentes y enriquecidos; puede abrir libremente una variedad de ellos para ayudar en la organización y el análisis diarios.",
    "28551": "Primeros auxilios de escritorio de computadora y flujo de limpieza de desorden",
    "28552": "Diseñado específicamente para computadoras de escritorio, proporciona distribución panorámica de las tareas pendientes actuales, borradores de trabajo, capturas de pantalla temporales, materiales para archivar y paquetes de instalación, y archiva de forma segura escritorios antiguos.",
    "28554": "Descargar directorio panorámico desvío y flujo de limpieza.",
    "28555": "Para el directorio mixto de navegadores y herramientas de descarga, Panorama distribuye paquetes de instalación de aplicaciones, documentos de oficina diarios, imágenes, audio y video, e imágenes de archivo comprimidas, y establece un período de protección de limpieza de vencimiento.",
