    "31332": "Motor de IA básico",
    "31333": "[Buscar archivos e imágenes por significado] Busque rápidamente fotografías y documentos según el significado general de su descripción. Al ocupar muy poca memoria, incluso las computadoras antiguas y las computadoras portátiles delgadas y livianas de gama baja pueden funcionar sin problemas. No soporta audio y video",
    "31334": "Requisitos de configuración extremadamente bajos · La primera opción para computadoras antiguas y portátiles delgadas y livianas",
    "31336": "[Cerebro de búsqueda integral más inteligente] Puede comprender oraciones, imágenes, audios y videos complejos de manera más profunda y precisa, y puede comprender mejor sus pensamientos cuando busca cosas. Recomendado para computadoras con 8GB o más de memoria.",
    "31337": "Configuración recomendada · Memoria del ordenador 8GB o superior",
    "31339": "[Estándar en computadoras portátiles de oficina delgadas y livianas] Admite el pulido inteligente de nombres de archivos, extracción de descripciones y análisis profundo de contenido. Este complemento no es necesario si el motor Firecore está habilitado.",
    "31340": "Requisitos de configuración extremadamente bajos · Funcionamiento puro de CPU",
    "31342": "Extracción de contenido de archivos",
    "31343": "[Marcado de imágenes y texto privados y sensibles] Identifique automáticamente imágenes y documentos/texto AIGC privados y sensibles que contengan descripciones explícitas y sensibles y márquelos para evitar vergüenza al verlos en una pantalla. Todas las computadoras funcionan extremadamente rápido.",
    "31344": "Requisitos mínimos de configuración · Procesamiento extremadamente rápido",
    "31346": "[Convierta automáticamente grabaciones y videos a texto] Comprenda el contenido del habla en videos y grabaciones y extraiga subtítulos. Puede buscar directamente \"quién dijo una determinada frase\". Consume más potencia informática, por lo que se recomiendan 16 GB de memoria o una tarjeta gráfica.",
    "31347": "Se requiere más potencia informática · Se recomiendan 16 GB de memoria o tarjeta gráfica",
    "31349": "[Admite clonación de voces exclusivas] Extractor de sonido incorporado, cargue una grabación para clonar voces exclusivas para leer artículos. Admite más de 50 sonidos cuidadosamente seleccionados y clones personalizados.",
    "31350": "Requisitos de configuración bajos · Computadora común para una pronunciación fluida",
    "31352": "[Lectura extremadamente rápida y que ahorra energía] Presione reproducir y el sonido comenzará instantáneamente en milisegundos. Tiene integradas más de 50 voces ricas y de alta calidad, y los documentos largos se pueden leer en voz alta sin problemas y sin demoras. Los portátiles normales, finos y ligeros, funcionan sin problemas.",
    "31353": "Requisitos de configuración extremadamente bajos · Pronunciación fluida para portátiles normales, finos y ligeros",
    "31354": "Estudio de mapeo local",
    "31355": "[Dibuja imágenes localmente en tu computadora] Ingresa una oración para dibujar hermosas imágenes localmente sin gastar un centavo. Requiere una mejor tarjeta gráfica discreta.",
