    "31672": "Confirmar para desinstalar el complemento",
    "31673": "Cambiará automáticamente a otro motor instalado del mismo tipo y eliminará los activos del motor actual. Se estima que se liberará aproximadamente {size} espacio en disco. ¿Estás seguro de desinstalarlo?",
    "31674": "El complemento y los recursos de su modelo se eliminarán de su computadora y se espera que liberen aproximadamente {size} espacio en disco. ¿Estás seguro de desinstalarlo?",
    "31675": "Confirmar el cambio y desinstalar",
    "31676": "Confirmar desinstalación",
    "31677": "El modelo fuera de línea liviano y de alta fidelidad admite hablantes enriquecidos y lectura natural en varios idiomas",
    "31678": "Explore la biblioteca de sonidos destacada, escúchela y agregue sus sonidos favoritos a su colección rápida.",
    "31679": "Las reglas de inclusión y las reglas de exclusión se pueden establecer al mismo tiempo y surtir efecto superpuestas.",
    "31680": "Se borraron las reglas de inclusión y ahora todas las cantidades se liberan de acuerdo con las reglas de exclusión.",
    "31681": "Las reglas de inclusión y exclusión se pueden establecer al mismo tiempo y entrar en vigor juntas; el sistema primero excluirá, luego filtrará de acuerdo con las reglas de inclusión y finalmente permitirá los archivos restantes.",
    "31682": "Guardar reglas de inclusión y exclusión",
    "31683": "La modificación de las reglas de inclusión y exclusión solo afecta a los archivos que se muestran en el directorio real y no toca ninguno de los archivos físicos originales en el disco de su computadora.",
    "31684": "Reglas de acceso a archivos (se pueden configurar al mismo tiempo)",
    "31685": "La superposición Incluir + Excluir entra en vigor",
    "31686": "Las reglas de inclusión y las reglas de exclusión son dos conjuntos independientes de configuraciones que se pueden establecer al mismo tiempo y superponerse para que surtan efecto. No es necesario elegir uno entre los dos. El sistema determina en el siguiente orden fijo:",
    "31687": "1. Exclusión dura del sistema",
    "31688": "2. Exclusiones específicas del directorio",
    "31689": "3. Incluir reglas",
    "31690": "4. Liberar por defecto",
    "31691": "Deje la regla de inclusión en blanco para indicar que no hay restricción en el formato y que se permitirán todas las extensiones excepto las exclusiones; después de completar, solo se permitirán estas extensiones. Las reglas de exclusión siempre entran en vigor primero y archivos como miniaturas y directorios de caché se pueden excluir con precisión bajo reglas de inclusión amplias.",
    "31692": "Deje la regla de inclusión en blanco: los archivos restantes se liberarán de acuerdo con la regla de exclusión.",
    "31693": "Para ser medido",
    "31694": "Actualmente no hay reglas de inclusión establecidas: hay {totalFiles} archivos en el directorio. A excepción de los archivos afectados por exclusiones estrictas del sistema y reglas de exclusión específicas de directorio, los {included} archivos restantes se incluirán en el análisis de IA.",
    "31695": "Actualmente no hay reglas de inclusión establecidas: excepto los archivos afectados por exclusiones estrictas del sistema y reglas de exclusión específicas de directorio, todos los demás archivos se incluirán en la indexación y el análisis de IA. Las reglas de inclusión se pueden agregar en cualquier momento y entrarán en vigencia al mismo tiempo que las reglas de exclusión.",
